  ],
  "readouts": [
    {
      "name": "E_i",
      "definition": "Total incompressible kinetic energy at equilibration time, defined as E_i = (1/2) integral |u_i(r, t_eq)|^2 d^2r = integral_0^infinity E_i(k) dk, where u_i is the incompressible (solenoidal) component of the density-weighted velocity field u = |Psi_C| v.",
      "unit": "dimensionless (scaled units)",
      "statistic": "Ensemble average over R=2000 (T=10^-6) and R=1000 (T=1) stochastic realizations.",
      "uncertainty": "Error bars denote 1 standard deviation.",
      "resolution": null,
      "anchors": [
        {
          "line_start": 187,
          "line_end": 200,
          "support": "Density-weighted velocity field u = |Psi_C| v, decomposition into compressible and incompressible components, and definition of E_i,c = (1/2) integral |u_i,c|^2 d^2r."
        },
        {
          "line_start": 394,
          "line_end": 413,
          "support": "E_i defined as (1/2) integral |u_i(r, t_eq)|^2 d^2r = integral_0^infinity E_i(k) dk."
        },
        {
          "line_start": 390,
          "line_end": 390,
          "support": "Each data point is averaged over (a) R=2000 and (b) R=1000 stochastic realizations. Error bars denote 1 standard deviation."
        }
      ]
    }
  ],
